#include <xc.h>
#include "canHandler.h"
#include "ioHandler.h"
#include "runnables.h"

void initBoard(void);

int main(void) 
{
    // Run initializations
    initBoard();
    canHandler_init();
    ioHandler_init();
    runnables_init();

    // Main runnable
    for(;;)
    {
        canHandler_run();
        ioHandler_run();
        runnables_run();
    }
}

void initBoard()
{
    // Setup clock to 32MHz, closest to 40
    OSCFRQ = 0b0110;   // 32 MHz

    // Select HFINTOSC on OSC1
    OSCCON1bits.NOSC = 0b110;  // HFINTOSC in OSC1
}